    20→    @ExceptionHandler(EntityNotFoundException.class)
    21→    public ResponseEntity<ErrorResponse> handleEntityNotFound(
    22→            EntityNotFoundException ex,
    23→            HttpServletRequest request) {
    24→        ErrorResponse error = new ErrorResponse(
